import type { Metadata } from "next";
import { Assistant } from "next/font/google";
import { NextIntlClientProvider } from "next-intl";
import { getMessages } from "next-intl/server";
import { notFound } from "next/navigation";
import { routing } from "@/i18n/routing";
import Header from "@/components/layout/Header";
import "../globals.css";

const assistant = Assistant({
  subsets: ["latin", "hebrew"],
  weight: ["300", "400", "500", "600", "700"],
  variable: "--font-assistant",
});

export const metadata: Metadata = {
  title: "מחיריסטה | Machirista — Israeli Supermarket Price Comparison",
  description: "Compare supermarket prices across all Israeli chains. Build your basket and find the cheapest store near you.",
};

export default async function LocaleLayout({
  children,
  params,
}: {
  children: React.ReactNode;
  params: Promise<{ locale: string }>;
}) {
  const { locale } = await params;

  if (!routing.locales.includes(locale as "he" | "en")) {
    notFound();
  }

  const messages = await getMessages();
  const isRtl = locale === "he";

  return (
    <html lang={locale} dir={isRtl ? "rtl" : "ltr"}>
      <body className={`${assistant.variable} font-sans bg-white text-stone-900 antialiased`}>
        <NextIntlClientProvider messages={messages}>
          <div className="min-h-screen flex flex-col">
            <Header locale={locale} />
            <main className="flex-1">
              {children}
            </main>
            <footer className="border-t border-stone-200 py-10 mt-24">
              <div className="max-w-6xl mx-auto px-6 flex flex-col sm:flex-row items-center justify-between gap-3 text-sm text-stone-400">
                <span className="font-semibold text-stone-600 tracking-tight">
                  {isRtl ? "מחיריסטה" : "Machirista"}
                </span>
                <span>© 2026 · {isRtl ? "נתונים מתעדכנים כל 3 שעות" : "Data refreshed every 3 hours"}</span>
              </div>
            </footer>
          </div>
        </NextIntlClientProvider>
      </body>
    </html>
  );
}
